		#region Constructors

		public InventoryForm() { /* for designer */ }

		public InventoryForm(WhsDocketLine inventoryLine)
			: base(inventoryLine)
		{
			AddPlugIns();
			AddMenuItems();

			CustomFieldsTabPage.RunWhenBindingOrFirstShown(delegate
			{
				ICustomLabelsProvider customLabelProvider = new WhsDocketLine.CustomLabelsProvider(inventoryLine);
				customLabelsUserControl1.CustomLabelsProvider = customLabelProvider;
			});

			HookEvents();
		}

		void AddPlugIns()
		{
			PlugIns.Add(ControllerIDs.eDocsPlugIn);
			PlugIns.Add(ControllerIDs.DocDataPlugIn);
		}

		void AddMenuItems()
		{
			ZFormMenuStrategy.AddActionsMenuItem(this, ResString.GetMultilingualString("7dd0c1e0-0135-48c7-a515-d8e1fbe7ac4a", "View Receipt"), ViewReceiptMenuItem_Click);
			ZFormMenuStrategy.AddActionsMenuItem(this, ResString.GetMultilingualString("04759ccb-afb2-463e-8003-908914f0c868", "Committed..."), CommittedStockMenuItem_Click);
		}

		void HookEvents()
		{
			if (DocketLine != null && DocketLine.Inventory.Count > 0)
			{
				DocketLine.Inventory[0].OnInventoryPrint += Inventory_OnInventoryPrint;
			}
		}

		void UnhookEvents()
		{
			if (DocketLine != null && DocketLine.Inventory.Count > 0)
			{
				DocketLine.Inventory[0].OnInventoryPrint -= Inventory_OnInventoryPrint;
			}
		}

