		}

		public void CommittedStockMenuItem_Click(object sender, EventArgs e)
		{
			InventoryHelper.ShowWhyInventoryIsCommitted(DocketLine);
		}

		void Inventory_OnInventoryPrint(object sender, WhsDocumentInventoryEventArgs e)
		{
			using (var form = new WhsDocumentInventoryOptionsForm(e.Options))
			{
				e.ContinueToPrint = ZFormModaliser.ShowDialogAndDispose(form) == DialogResult.Yes;
			}

			//var form = new WhsDocumentInventoryOptionsForm(e.Options);
			//e.ContinueToPrint = ZFormModaliser.ShowDialogAndDispose(form) == DialogResult.Yes;
		}

